  parentTaskId: r.parent_task_id,
  subtasks: subtasks.filter((s) => s.task_id === r.id).map((s) => ({ id: s.id, taskId: s.task_id, title: s.title, done: s.done === 1 [… 4,460 characters omitted]  task.recurrence ? JSON.stringify(task.recurrence) : null,
        completedAt: task.status === 'done' ? (previous.status === 'done' ? previous.completed_at : now) : null })
    replaceSubtasks(db, id, task.subtasks)
